let failures = 0;
function assert(cond, msg) {
  if (cond) { console.log("  ok:", msg); }
  else { console.log("  FAIL:", msg); failures++; }
}

// wait for script to run
setTimeout(() => {
  const lab = window.spreadPlateLab;
  assert(!!lab, "window.spreadPlateLab exists");

  // markers
  const doc = window.document;
  const required = [
    'lab-root','equipment-yeast-broth','equipment-cotton-plug','equipment-agar-plate',
    'equipment-inoculation-loop','equipment-alcohol-lamp','equipment-clean-bench',
    'step-instruction','feedback','progress'
  ];
  required.forEach(t => assert(!!doc.querySelector(`[data-testid="${t}"]`), `marker ${t} present`));

  // action buttons
  ['sterilize','cool','sample','inoculate','spread','incubate','reset'].forEach(a =>
    assert(!!doc.querySelector(`[data-action="${a}"]`), `action button ${a} present`));

  // draggable
  ['equipment-yeast-broth','equipment-cotton-plug','equipment-agar-plate',
   'equipment-inoculation-loop','equipment-alcohol-lamp','equipment-clean-bench']
    .forEach(t => assert(doc.querySelector(`[data-testid="${t}"]`).getAttribute('draggable')==='true', `${t} draggable=true`));

  // initial state
  let s = lab.getState();
  assert(s.step === 'sterilize', `initial step sterilize (got ${s.step})`);
  assert(s.completed === false, 'initial not completed');
  assert(Array.isArray(s.history) && s.history.length === 0, 'history empty array');

  // lab-root data-step
  assert(doc.querySelector('[data-testid="lab-root"]').getAttribute('data-step') === 'sterilize', 'lab-root data-step sterilize');

  // invalid action: sample before sterilize
  let r = lab.perform('sample');
  assert(r.ok === false, 'sample out of order ok=false');
  assert(/message/i.test('message') || typeof r.message === 'string', 'message is string');
  assert(lab.getState().step === 'sterilize', 'step unchanged after invalid');
  assert(lab.getState().history.length === 0, 'history unchanged after invalid');

  // full valid sequence
  const seq = ['sterilize','cool','sample','inoculate','spread','incubate'];
  seq.forEach(a => {
    const res = lab.perform(a);
    assert(res.ok === true, `perform ${a} ok`);
  });
  s = lab.getState();
  assert(s.step === 'complete', `final step complete (got ${s.step})`);
  assert(s.completed === true, 'completed=true');
  assert(JSON.stringify(s.history) === JSON.stringify(seq), 'history matches sequence');
  assert(doc.querySelector('[data-testid="lab-root"]').getAttribute('data-step') === 'complete', 'lab-root data-step complete');

  // out of order after complete
  r = lab.perform('sterilize');
  assert(r.ok === false, 'sterilize after complete ok=false');

  // repeated idempotency: performing current step when already complete
  r = lab.perform('incubate');
  assert(r.ok === false, 'incubate again ok=false (already complete)');
  assert(lab.getState().step === 'complete', 'still complete');

  // reset
  r = lab.reset();
  assert(r.ok === true, 'reset ok');
  s = lab.getState();
  assert(s.step === 'sterilize', 'reset step sterilize');
  assert(s.completed === false, 'reset not completed');
  assert(s.history.length === 0, 'reset history empty');
  assert(doc.querySelector('[data-testid="lab-root"]').getAttribute('data-step') === 'sterilize', 'lab-root reset data-step');

  // unknown action
  r = lab.perform('foobar');
  assert(r.ok === false, 'unknown action ok=false');

  // perform a wrong skip (inoculate while at sterilize) - guidance
  r = lab.perform('inoculate');
  assert(r.ok === false && r.message.length > 0, 'inoculate out of order returns message');

  // partial then reset path
  lab.perform('sterilize');
  assert(lab.getState().step === 'cool', 'after sterilize -> cool');
  lab.reset();

  console.log("");
  if (failures === 0) console.log("ALL CHECKS PASSED");
  else console.log(failures + " CHECK(S) FAILED");
  process.exit(failures === 0 ? 0 : 1);
